low={'Hyderabad':175,'Mumbai':180,'Bengaluru':185}
avg=sum(low.values())/3
below=sorted(k for k,v in low.items() if v<avg)
opts={'A':['Hyderabad'],'B':['Bengaluru'],'C':['Mumbai'],'D':['Hyderabad','Mumbai']}
fits=[k for k,v in opts.items() if sorted(v)==below]
assert fits==['A']
